import sys
from collections import deque

def find_dag(t, cases):
    results = []
    for n, m, edges in cases:
        graph = [[] for _ in range(n)]
        in_degree = [0] * n
        undirected_edges = []

        for t_i, x_i, y_i in edges:
            if t_i == 1:
                graph[x_i - 1].append(y_i - 1)
                in_degree[y_i - 1] += 1
            else:
                undirected_edges.append((x_i - 1, y_i - 1))

        queue = deque([i for i in range(n) if in_degree[i] == 0])
        topo_order = []

        while queue:
            node = queue.popleft()
            topo_order.append(node)
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        if len(topo_order) != n:
            results.append("NO")
            continue

        directed_edges = []
        for x, y in undirected_edges:
            if topo_order.index(x) < topo_order.index(y):
                directed_edges.append((x + 1, y + 1))
            else:
                directed_edges.append((y + 1, x + 1))

        for x, y in edges:
            if x != y:
                directed_edges.append((x, y))

        results.append("YES")
        for edge in directed_edges:
            results.append(f"{edge[0]} {edge[1]}")

    return "\n".join(results)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    t = int(input[index])
    index += 1
    cases = []
    for _ in range(t):
        n, m = map(int, input[index].split())
        index += 1
        edges = []
        for _ in range(m):
            t_i, x_i, y_i = map(int, input[index].split())
            edges.append((t_i, x_i, y_i))
            index += 1
        cases.append((n, m, edges))
    result = find_dag(t, cases)
    print(result)

if __name__ == "__main__":
    main()
